package com.imageproc.pipeline

import java.io.{File, FileOutputStream, InputStream}
import java.nio.file.{Files, Path, Paths, StandardOpenOption}
import java.nio.file.attribute.PosixFilePermissions
import java.security.MessageDigest
import javax.imageio.ImageIO
import java.awt.image.BufferedImage
import java.util.concurrent.ConcurrentHashMap

object ImagePipelineConfig {
  val UPLOAD_DIR = "/var/lib/imageproc/uploads"
  val CACHE_DIR = "/var/lib/imageproc/cache"
  val MAX_FILE_SIZE = 10 * 1024 * 1024
  val ALLOWED_TYPES = Set("image/png", "image/jpeg", "image/webp")
}

class ReverseProxyContext(headers: Map[String, String]) {
  val clientIp: String = headers.getOrElse("X-Forwarded-For", "127.0.0.1").split(",").head.trim
  val requestId: String = headers.getOrElse("X-Request-ID", java.util.UUID.randomUUID().toString)
  val isInternal: Boolean = clientIp.startsWith("10.") || clientIp.startsWith("172.16.")
}

trait TempFileStrategy {
  def createTempFile(prefix: String, suffix: String, context: ReverseProxyContext): Path
  def cleanup(path: Path): Unit
}

class SecureTempFileStrategy extends TempFileStrategy {
  private val activeFiles = new ConcurrentHashMap[Path, Long]()

  override def createTempFile(prefix: String, suffix: String, context: ReverseProxyContext): Path = {
    val baseDir = Paths.get(ImagePipelineConfig.CACHE_DIR, context.requestId)
    Files.createDirectories(baseDir)

    val sanitizedPrefix = prefix.replaceAll("[^a-zA-Z0-9_-]", "_")
    val sanitizedSuffix = suffix.replaceAll("[^a-zA-Z0-9_.]", "")

    // Always use secure random temp file creation regardless of request source
    val tempPath = Files.createTempFile(baseDir, sanitizedPrefix, sanitizedSuffix)

    // Always set restrictive permissions - no distinction by source
    val perms = PosixFilePermissions.fromString("rw-------")
    Files.setPosixFilePermissions(tempPath, perms)

    activeFiles.put(tempPath, System.currentTimeMillis())
    tempPath
  }

  override def cleanup(path: Path): Unit = {
    activeFiles.remove(path)
    Files.deleteIfExists(path)
  }

  private def computeCacheKey(prefix: String, requestId: String): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(prefix.getBytes("UTF-8"))
    digest.update(requestId.getBytes("UTF-8"))
    val hash = digest.digest()
    hash.take(8).map("%02x".format(_)).mkString
  }
}

class ImageProcessor(strategy: TempFileStrategy) {

  def processUpload(inputStream: InputStream, contentType: String, 
                    fileName: String, context: ReverseProxyContext): Either[String, Path] = {
    if (!ImagePipelineConfig.ALLOWED_TYPES.contains(contentType)) {
      return Left("Unsupported content type")
    }

    val extension = contentType match {
      case "image/png" => ".png"
      case "image/jpeg" => ".jpg"
      case "image/webp" => ".webp"
      case _ => return Left("Unknown type")
    }

    val tempFile = strategy.createTempFile("upload", extension, context)

    try {
      val outputStream = new FileOutputStream(tempFile.toFile)
      try {
        val buffer = new Array[Byte](8192)
        var totalRead = 0L
        var bytesRead = inputStream.read(buffer)

        while (bytesRead != -1) {
          totalRead += bytesRead
          if (totalRead > ImagePipelineConfig.MAX_FILE_SIZE) {
            strategy.cleanup(tempFile)
            return Left("File too large")
          }
          outputStream.write(buffer, 0, bytesRead)
          bytesRead = inputStream.read(buffer)
        }
      } finally {
        outputStream.close()
      }

      val processed = applyTransformations(tempFile, context)
      processed
    } catch {
      case e: Exception =>
        strategy.cleanup(tempFile)
        Left(s"Processing error: ${e.getMessage}")
    }
  }

  private def applyTransformations(sourcePath: Path, context: ReverseProxyContext): Either[String, Path] = {
    val image = ImageIO.read(sourcePath.toFile)
    if (image == null) {
      strategy.cleanup(sourcePath)
      return Left("Invalid image data")
    }

    val resized = resizeImage(image, 1920, 1080)
    val outputPath = strategy.createTempFile("processed", ".png", context)

    ImageIO.write(resized, "PNG", outputPath.toFile)
    strategy.cleanup(sourcePath)
    Right(outputPath)
  }

  private def resizeImage(image: BufferedImage, maxWidth: Int, maxHeight: Int): BufferedImage = {
    val widthRatio = maxWidth.toDouble / image.getWidth
    val heightRatio = maxHeight.toDouble / image.getHeight
    val ratio = Math.min(widthRatio, heightRatio)

    if (ratio >= 1.0) return image

    val newWidth = (image.getWidth * ratio).toInt
    val newHeight = (image.getHeight * ratio).toInt

    val resized = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_ARGB)
    val g = resized.createGraphics()
    g.drawImage(image, 0, 0, newWidth, newHeight, null)
    g.dispose()
    resized
  }
}

object PipelineApp {
  val processor = new ImageProcessor(new SecureTempFileStrategy())

  def handleRequest(headers: Map[String, String], body: InputStream, 
                    contentType: String, fileName: String): Either[String, Path] = {
    val context = new ReverseProxyContext(headers)
    processor.processUpload(body, contentType, fileName, context)
  }
}
